method check_dict_case(dict: map<string, string>) returns (result: bool)
    requires dict != null
    requires |dict| > 0 // The dictionary must not be empty
    ensures result == (AllKeysLowerCase(dict) || AllKeysUpperCase(dict))

    // Helper function to check if all keys are lowercase
    function AllKeysLowerCase(d: map<string, string>): bool
        reads d
        decreases |d|
    {
        forall k :: k in d.Keys() ==> IsLower(k)
    }

    // Helper function to check if all keys are uppercase
    function AllKeysUpperCase(d: map<string, string>): bool
        reads d
        decreases |d|
    {
        forall k :: k in d.Keys() ==> IsUpper(k)
    }

    // Helper function to check if a string is in lowercase
    function IsLower(s: string): bool
        reads s
    {
        forall i :: 0 <= i < |s| ==> 'a' <= s[i] && s[i] <= 'z' 
    }

    // Helper function to check if a string is in uppercase
    function IsUpper(s: string): bool
        reads s
    {
        forall i :: 0 <= i < |s| ==> 'A' <= s[i] && s[i] <= 'Z'
    }
